package org.sleepmonitor.app;
import java.util.*;
import android.graphics.*;
import android.graphics.pdf.PdfDocument;
import java.io.*;
final class SleepReport {
 static final String[] names={"Rücken","Links","Rechts","Bauch","Unbekannt","Gesamt"};
 static int position(String s){return Math.max(0,Arrays.asList("Ruecken","Links","Rechts","Bauch").contains(s)?Arrays.asList("Ruecken","Links","Rechts","Bauch").indexOf(s):4);}
 static final class Event {long start,end;int pos;boolean complete;Event(long s,long e,int p,boolean c){start=s;end=e;pos=p;complete=c;}}
 static ArrayList<Event> events(List<MonitorService.Point> a,int drop){ArrayList<Event> out=new ArrayList<>();ArrayDeque<MonitorService.Point> base=new ArrayDeque<>();long onset=-1,prev=-1;int ref=0,pos=4;boolean mixed=false;for(MonitorService.Point q:a){if(prev>=0&&(q.time-prev>3000||q.time<=prev)){if(onset>=0&&prev-onset>=10000)out.add(new Event(onset,prev,mixed?4:pos,false));base.clear();onset=-1;}while(!base.isEmpty()&&q.time-base.peekFirst().time>30000)base.removeFirst();if(onset<0){ref=q.oxygen;for(MonitorService.Point x:base)ref=Math.max(ref,x.oxygen);if(ref-q.oxygen>=drop){onset=q.time;pos=position(q.position);mixed=false;}}else if(ref-q.oxygen<drop){if(prev-onset>=10000)out.add(new Event(onset,q.time,mixed?4:pos,true));onset=-1;}else if(position(q.position)!=pos)mixed=true;base.addLast(q);prev=q.time;}if(onset>=0&&prev-onset>=10000)out.add(new Event(onset,prev,mixed?4:pos,false));return out;}
 static final class Bucket {long ms,t90,t88,ox,hr,hrms;int min=101,hmin=301,hmax=0,n3,n4,completed;long duration,max;void add(MonitorService.Point q,long dt){ms+=dt;ox+=q.oxygen*dt;min=Math.min(min,q.oxygen);if(q.oxygen<90)t90+=dt;if(q.oxygen<88)t88+=dt;if(q.pulse>0){hr+=q.pulse*dt;hrms+=dt;hmin=Math.min(hmin,q.pulse);hmax=Math.max(hmax,q.pulse);}}String rate(int n){return ms==0?"–":fmt(n*3600000.0/ms);}String mean(){return ms==0?"–":fmt((double)ox/ms);}String pulse(){return hrms==0?"–":fmt((double)hr/hrms)+" / "+hmin+" / "+hmax;} }
 final String batterySummary; final Bucket[] buckets=new Bucket[6];final ArrayList<Event> e3,e4;final long start,end;int changes;SleepReport(List<MonitorService.Point> a){for(int i=0;i<6;i++)buckets[i]=new Bucket();start=a.isEmpty()?0:a.get(0).time;end=a.isEmpty()?0:a.get(a.size()-1).time;for(int i=0;i+1<a.size();i++){MonitorService.Point q=a.get(i),n=a.get(i+1);long dt=n.time-q.time;if(dt<=0||dt>3000)continue;int k=position(q.position),j=position(n.position);buckets[k].add(q,dt);buckets[5].add(q,dt);if(k<4&&j<4&&k!=j)changes++;}batterySummary=batteryStats(a);e3=events(a,3);e4=events(a,4);for(Event e:e3){for(int k:new int[]{e.pos,5}){Bucket z=buckets[k];z.n3++;if(e.complete){z.completed++;z.duration+=e.end-e.start;z.max=Math.max(z.max,e.end-e.start);}}}for(Event e:e4){buckets[e.pos].n4++;buckets[5].n4++;}}
 static String batteryStats(List<MonitorService.Point> a){StringBuilder s=new StringBuilder("Akku (erste / letzte gültige Messung / Minimum)");for(int k=0;k<2;k++){int first=-1,last=-1,min=101;for(MonitorService.Point q:a){int v=k==0?q.oBattery:q.wBattery;if(v<0)continue;if(first<0)first=v;last=v;min=Math.min(min,v);}s.append("\n").append(k==0?"Checkme: ":"WIT (geschätzt): ").append(first<0?"keine Daten":first+" / "+last+" / "+min+" %");}return s.toString();}
 static String fmt(double v){return String.format(Locale.GERMANY,"%.1f",v);}
 static String date(long t){return new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm:ss",Locale.GERMANY).format(new Date(t));}
 String summary(){Bucket z=buckets[5];return "Schlafbericht · experimentelle Oximetrie\n"+date(start)+" – "+date(end)+"\nMessspanne: "+fmt((end-start)/60000.0)+" min | Gültig: "+fmt(z.ms/60000.0)+" min\nODI3: "+z.rate(z.n3)+"/h | ODI4: "+z.rate(z.n4)+"/h\nSpO₂ Ø "+z.mean()+" % | Lagewechsel: "+changes;}
 String detail(int i){Bucket z=buckets[i];return names[i]+" | "+fmt(z.ms/60000.0)+" min\nSpO₂ Ø / min: "+z.mean()+" / "+(z.ms==0?"–":z.min)+" %\nAbfälle 3 / 4 pp: "+z.n3+" / "+z.n4+" | ODI3 / ODI4: "+z.rate(z.n3)+" / "+z.rate(z.n4)+" /h\nT90 / T88 (<): "+fmt(z.t90/60000.0)+" / "+fmt(z.t88/60000.0)+" min"+(z.ms>0?" ("+fmt(z.t90*100.0/z.ms)+" / "+fmt(z.t88*100.0/z.ms)+" %)":"")+"\nPuls Ø / min / max: "+z.pulse()+" bpm\nAbfalldauer Ø / max (vollst. ODI3): "+(z.completed==0?"–":fmt(z.duration/1000.0/z.completed)+" / "+fmt(z.max/1000.0))+" s";}
 static final String METHOD="ODI: Abfall um 3 bzw. 4 Prozentpunkte für mindestens 10 s; Referenz: Maximum der vorigen 30 s. Gültige Messzeit: Intervalle bis 3 s zwischen gültigen Werten. Lagewechsel während eines Abfalls: unbekannt. Kein EEG, kein Atemfluss, kein AHI. Nicht medizinisch validiert.";
 String full(){StringBuilder s=new StringBuilder(summary());for(int i=5;i>=0;i--)s.append("\n\n").append(detail(i));return s.append("\n\nMesslücken: ").append(fmt(Math.max(0,end-start-buckets[5].ms)/60000.0)).append(" min\n").append(batterySummary).append("\n").append(METHOD).toString();}
 static void lines(Canvas c,Paint p,String s,int x,int y,int width){for(String line:s.split("\n")){while(!line.isEmpty()){int n=p.breakText(line,true,width,null);if(n==0)n=1;c.drawText(line.substring(0,n),x,y,p);line=line.substring(n);y+=15;}if(line.isEmpty())y+=3;}}
 void pdf(OutputStream out,List<MonitorService.Point> a)throws IOException{PdfDocument d=new PdfDocument();try{Paint p=new Paint(3);p.setColor(Color.BLACK);p.setTextSize(12);PdfDocument.Page pg=d.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());Canvas c=pg.getCanvas();lines(c,p,"SleepMonitor 2.4 | Oximetrie zu Hause\nCheckme O2 Ultra + WIT WT901BLE67\n"+summary()+"\n\n"+detail(5)+"\n\n"+detail(0)+"\n\n"+detail(1)+"\n\n"+detail(2),36,44,523);d.finishPage(pg);pg=d.startPage(new PdfDocument.PageInfo.Builder(595,842,2).create());c=pg.getCanvas();lines(c,p,detail(3)+"\n\n"+detail(4)+"\n\n"+batterySummary+"\n\n"+METHOD+"\nOrientierung: ASA Guidelines 2024, doi:10.1093/sleep/zsae107.\nMesslücken: "+fmt(Math.max(0,end-start-buckets[5].ms)/60000.0)+" min",36,44,523);draw(c,p,a,36,350,523,380);d.finishPage(pg);pg=d.startPage(new PdfDocument.PageInfo.Builder(595,842,3).create());c=pg.getCanvas();p.setTextSize(12);lines(c,p,"Akkuverlauf\n"+batterySummary+"\nWIT-Prozentwerte aus Spannung geschätzt; fehlende Werte nicht als 0 dargestellt.",36,44,523);float left=50,top=180,width=490,height=200;for(int v=0;v<=100;v+=20){p.setColor(Color.GRAY);float yy=top+(100-v)*height/100;c.drawLine(left,yy,left+width,yy,p);c.drawText(""+v,left-25,yy,p);}long span=Math.max(1,end-start);for(int k=0;k<2;k++){MonitorService.Point prev=null;for(MonitorService.Point q:a){int v=k==0?q.oBattery:q.wBattery;if(v<0){prev=null;continue;}p.setColor(k==0?0xff2878d0:0xff20984e);float xx=left+(q.time-start)/(float)span*width,yy=top+(100-v)*height/100;if(prev!=null&&q.time-prev.time<=3000){int pv=k==0?prev.oBattery:prev.wBattery;c.drawLine(left+(prev.time-start)/(float)span*width,top+(100-pv)*height/100,xx,yy,p);}else c.drawPoint(xx,yy,p);prev=q;}}p.setColor(Color.BLACK);c.drawText("Checkme blau / WIT grün",left,top+height+35,p);d.finishPage(pg);d.writeTo(out);}finally{d.close();}}
 void draw(Canvas c,Paint p,List<MonitorService.Point> a,float x,float y,float w,float h){long span=Math.max(1,end-start);p.setTextSize(11);p.setColor(Color.BLACK);c.drawText("SpO₂ (%) / ODI3 / ODI4 / Puls / Körperlage",x,y,p);int[] colors={0xffd53535,0xff20984e,0xff2878d0,0xffba8800,0xff888888};MonitorService.Point prev=null;for(MonitorService.Point q:a){float xx=x+(q.time-start)/(float)span*w;if(prev!=null&&q.time-prev.time<=3000&&q.time>prev.time){float px=x+(prev.time-start)/(float)span*w;p.setColor(colors[position(prev.position)]);c.drawLine(px,y+20+(100-prev.oxygen)*1.5f,xx,y+20+(100-q.oxygen)*1.5f,p);c.drawRect(px,y+300,xx,y+315,p);if(prev.pulse>0&&q.pulse>0){p.setColor(0xff8050a0);c.drawLine(px,y+285-prev.pulse*.35f,xx,y+285-q.pulse*.35f,p);}}prev=q;}for(Event e:e3){p.setColor(0xffba8800);float xx=x+(e.start-start)/(float)span*w;c.drawLine(xx,y+175,xx,y+188,p);}for(Event e:e4){p.setColor(0xffd53535);float xx=x+(e.start-start)/(float)span*w;c.drawLine(xx,y+195,xx,y+208,p);}p.setColor(Color.BLACK);for(int i=0;i<=4;i++){long t=start+(end-start)*i/4;c.drawText(new java.text.SimpleDateFormat("HH:mm",Locale.GERMANY).format(new Date(t)),x+(w-30)*i/4,y+339,p);}c.drawText("Rücken rot | Links grün | Rechts blau | Bauch gelb | unbekannt grau",x,y+360,p);}
}
